var a=[{title:`Twój całkowity stres`,text:`Trening to tylko część stresu, który nosisz. Słaby sen, podróże, wymagająca praca, napięcie emocjonalne, upał i niedawna choroba mogą wpływać na koncentrację, koordynację i to, jak ciężka wydaje się praca. Gotowość nie jest diagnozą i żaden pojedynczy wynik jej nie oddaje.`},{title:`Prosta kontrola`,text:`Przed treningiem zwróć uwagę na sen, energię, motywację, ból mięśni i wszelkie nowe objawy. Porównuj je z tym, co jest normalne dla Ciebie, a nie z cudzymi liczbami. Rozgrzewka daje drugą kontrolę: jeśli ruchy wydają się nieoczekiwanie ciężkie lub kontrola szwankuje, wymagający trening może wymagać dostosowania.`},{title:`Dostosowanie w słabszy dzień`,text:`W dzień niskiej energii zmniejsz obciążenie, skróć trening, wybierz prostsze ćwiczenia lub idź na spokojny spacer. W normalny dzień wykonaj plan tak, jak jest zapisany. Nie zamieniaj każdego krótkiego spadku w dzień odpoczynku. Trendy z kilku treningów mówią Ci więcej niż jedna ocena.`},{title:`Choroba i bezpieczeństwo`,text:`Gorączka, choroba dotykająca całe ciało, objawy w klatce piersiowej lub niezwykła zadyszka to powody, by pominąć ciężki trening i zasięgnąć porady medycznej. Popularny „test szyi” to tylko przybliżona reguła i nie upoważnia do ćwiczeń podczas choroby.`},{title:`Korzystanie z TrainUp`,text:`TrainUp nie zaleca ciężarów, więc obciążenie wybierasz każdego dnia sam. Twój plan zmienia się tylko wtedy, gdy ponownie go wygenerujesz, na podstawie wysiłku (RPE), który oceniasz po każdym treningu, zgłoszonego bólu i tego, jaką część każdego treningu kończysz.`}];var o=[{label:`CDC: zalecenia dotyczące snu`,url:`https://www.cdc.gov/sleep/about/`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: ból w klatce piersiowej i objawy alarmowe`,url:`https://www.nhs.uk/symptoms/chest-pain/`}];var n={sections:a,sources:o};export{n as default,a as sections,o as sources};